790|     //   这与本段的设计意图（工具路径是增强，绝不该有能力把整轮弄死）正好相反。
791|     //   现在改用**与 pipeline 同一个抽取器**（interpreter.js 的 extractJson：容忍围栏与前后废话，
792|     //   取首 { 到末 } 再 JSON.parse）：只有**真能 parse 成对象**才认，否则照旧回落重跑一次。
793|     const toolJson = extractJson(loop.text)
794|     const looksLikeJson = toolJson.ok === true && !toolJson.recovered && toolJson.value !== null && typeof toolJson.value === 'object'
795|     if (loop.ok && !loop.empty && looksLikeJson) {
796|       return { text: loop.text, ms: Date.now() - t0, via: 'tools', context: {
797|         toolRounds: loop.rounds, toolCalls: loop.toolCalls, toolNames: loop.names,
798|         toolCapped: loop.capped === true, toolTrace: loop.trace, toolMs: loop.ms,
799|         toolRoot: loop.root, toolsEnabled: true, toolsReason: tools.reason || 'enabled',
800|       }, usage: loop.usageSum || loop.usage || null }
801|     }
802|     // 报错 / 产出为空 ⇒ **回落**：再跑一次无工具的。这次回落本身要留痕（0.5 的红旗 6：
803|     // 工具循环降级在界面上毫无提示，用户只看到"产出怪怪的"）。
804|     // **回落也要交代代价**：`toolCalls/toolMs` 保留真实数字——那几次调用是真花掉了。
805|     const fell = {
806|       toolRounds: loop.rounds, toolCalls: loop.toolCalls, toolNames: loop.names,
807|       toolCapped: loop.capped === true, toolTrace: loop.trace, toolMs: loop.ms,
808|       toolRoot: loop.root, toolsEnabled: true, toolsReason: tools.reason || 'enabled',
809|       toolLoopError: String(loop.error || (loop.empty ? 'empty-output' : (looksLikeJson ? 'unknown' : ((toolJson.recovered || toolJson.code === 'BAD_JSON') ? 'tools-answer-bad-json' : 'tools-answer-not-json')))),
810|       toolFallback: 'no-tools-retry',
811|     }
812|     if(signal?.aborted){
813|       const usage=loop.usageSum || loop.usage || null,known=!!(usage && Object.values(usage).some(Number.isFinite))
814|       return {text:'',error:'cancelled',via:'tools-cancelled',usage,usageComplete:!!(usage && Number.isFinite(usage.totalTokens)),
815|         context:{...fell,toolFallback:'cancelled-no-retry',usageComplete:!!(usage && Number.isFinite(usage.totalTokens)),usageKnownCalls:known?1:0,usageUnknownCalls:known?0:1}}
816|     }
817|     const r2 = await plainDrain(() => llm.stream(withSignal({
818|       // ⚠ 回落这一次**必须换掉系统提示词**：开着工具时 `sys` 里带着"你可以用 read/glob/grep 查证"的整段说明，
819|       // 而我们这次**不传工具** ⇒ 模型只会回答"我打算去读哪些文件……"这样的散文 ⇒ 解析不出那份 JSON ⇒
820|       // 又变成 `noop`/`no-packet`。这正是用户实测"开只读工具必定 no-packet"的第二段机制。
821|       provide

